#include <stdio.h>
#include <stdbool.h>

bool checkPerfectNumber(int num) {
    if (num <= 1) {
        return false;
    }

    long long total = 1;
    for (int d = 2; (long long)d * d <= num; d++) {
        if (num % d == 0) {
            total += d;
            if ((long long)d * d != num) {
                total += num / d;
            }
        }
    }

    return total == num;
}

